INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2025-s0-0', 'exam-calculus-2-2025', 'exam-calculus-2-2025-sec-0', 0, '设向量满足，则必有（）.', '设向量 $\\vec{a},\\vec{b}$ 满足 $|\\vec{a} -\\vec{b}| = |\\vec{a} +\\vec{b} |$ ，则必有（）.', '["$\\\\vec{a} -\\\\vec{b} = \\\\vec{0}$","$\\\\vec{a} +\\\\vec{b} = \\\\vec{0}$","$\\\\vec{a}\\\\cdot \\\\vec{b} = 0$","$\\\\vec{a}\\\\times \\\\vec{b} = \\\\vec{0}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2025长沙理工大学高数A（二）期末', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
