INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2025-s0-2', 'exam-calculus-2-2025', 'exam-calculus-2-2025-sec-0', 0, '函数，则在点(1,1)处的全微', '函数 $z = 3^{xy}$ ，则在点(1,1)处的全微分 $dz = (\\quad)$', '["$dx$","$dy$","$3(dx + dy)\\\\ln 3$","$dx + dy$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2025长沙理工大学高数A（二）期末', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2025-s0-3', 'exam-calculus-2-2025', 'exam-calculus-2-2025-sec-0', 0, '设C是按逆时针方向绕行的圆周曲', '设C是按逆时针方向绕行的圆周曲线 $x^{2}+y^{2}=R^{2}$ ，则 $\\oint_{C}xy^{2}dy-x^{2}ydx=(\\quad)$ .', '["$\\\\int_{0}^{2\\\\pi}d\\\\theta\\\\int_{0}^{R}r^{3}dr$","$\\\\int_{0}^{2\\\\pi}d\\\\theta\\\\int_{0}^{R}r^{2}dr$","$-\\\\int_{0}^{2\\\\pi}d\\\\theta\\\\int_{0}^{R}4r^{3}\\\\sin\\\\theta\\\\cos\\\\theta dr$","$\\\\int_{0}^{2\\\\pi}d\\\\theta\\\\int_{0}^{R}R^{2}dr$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2025长沙理工大学高数A（二）期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2025-s0-4', 'exam-calculus-2-2025', 'exam-calculus-2-2025-sec-0', 0, '下列正项级数中，收敛的是（）.', '下列正项级数中，收敛的是（）.', '["$\\\\sum_{n=1}^{\\\\infty}\\\\frac{5^{n}-3^{n}}{4^{n}}$","$\\\\sum_{n=0}^{\\\\infty}\\\\frac{n}{2^{n}}$","$\\\\sum_{n=1}^{\\\\infty}\\\\frac{1}{\\\\sqrt{n}}$","$\\\\sum_{n=1}^{\\\\infty}\\\\frac{n+1}{n^{2}}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2025长沙理工大学高数A（二）期末', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
